const { app, BrowserWindow, globalShortcut, ipcMain, screen, Tray, Menu, nativeImage, clipboard, shell } = require('electron');
const path = require('path');
const fs = require('fs');
const { spawn } = require('child_process');
const koffi = require('koffi');

// El nombre debe fijarse ANTES de resolver app.getPath('userData'),
// para que dev y empaquetado compartan la misma carpeta de configuración.
app.setName('Actions Ring');

// --- Win32 API via koffi (sin PowerShell, sin execSync) ---
const user32 = koffi.load('user32.dll');
const kernel32 = koffi.load('kernel32.dll');
const psapi = koffi.load('psapi.dll');

// Tipos
const HWND = koffi.pointer('HWND', koffi.opaque());
const HANDLE = koffi.pointer('HANDLE', koffi.opaque());
const DWORD = koffi.alias('DWORD', 'uint32');
const WNDENUMPROC = koffi.proto('WNDENUMPROC', 'bool', [HWND, 'intptr']);

// Constantes SendInput
const INPUT_KEYBOARD = 1;
const KEYEVENTF_KEYUP = 0x0002;
const KEYEVENTF_EXTENDEDKEY = 0x0001;
const KEYEVENTF_UNICODE = 0x0004;

// sizeof(INPUT) en x64 = 4 (type) + 4 (padding) + 32 (union MOUSEINPUT) = 40.
// Dentro de la union, KEYBDINPUT arranca en el offset 8 del struct:
//   wVk @8, wScan @10, dwFlags @12, time @16, dwExtraInfo @24 (alineado a 8).
const INPUT_SIZE = 40;
const OFF_TYPE = 0;
const OFF_VK = 8;
const OFF_SCAN = 10;
const OFF_FLAGS = 12;
const OFF_TIME = 16;
const OFF_EXTRA = 24;

// Funciones Win32
const GetForegroundWindow = user32.func('GetForegroundWindow', HWND, []);
const GetWindowThreadProcessId = user32.func('GetWindowThreadProcessId', DWORD, [HWND, koffi.out(koffi.pointer('uint32'))]);
const SetForegroundWindow = user32.func('SetForegroundWindow', 'bool', [HWND]);
const OpenProcess = kernel32.func('OpenProcess', HANDLE, [DWORD, 'bool', DWORD]);
const CloseHandle = kernel32.func('CloseHandle', 'bool', [HANDLE]);
const GetModuleBaseNameW = psapi.func('GetModuleBaseNameW', DWORD, [HANDLE, 'void *', 'uint16 *', DWORD]);
const SendInput = user32.func('SendInput', 'uint32', ['uint32', 'void *', 'int32']);
const EnumWindows = user32.func('EnumWindows', 'bool', [koffi.pointer(WNDENUMPROC), 'intptr']);
const IsWindowVisible = user32.func('IsWindowVisible', 'bool', [HWND]);
const GetWindowTextLengthW = user32.func('GetWindowTextLengthW', 'int32', [HWND]);
const GetCurrentThreadId = kernel32.func('GetCurrentThreadId', DWORD, []);
const AttachThreadInput = user32.func('AttachThreadInput', 'bool', [DWORD, DWORD, 'bool']);
const SetFocus = user32.func('SetFocus', HWND, [HWND]);

const PROCESS_QUERY_INFORMATION = 0x0400;
const PROCESS_VM_READ = 0x0010;

// --- Estado global ---
let overlay = null;
let settingsWin = null;
let tray = null;
let config = null;
let lastActiveApp = null;
let lastActiveHwnd = null;
let clipboardHistory = [];
let clipboardTimer = null;
let activeHotkey = null;
let recordingActive = false;
let overlayShownAt = 0;

const DEFAULT_HOTKEY = 'Control+Alt+Space';
const MAX_CLIPBOARD_HISTORY = 20;

const DEFAULT_CONFIG = {
  hotkey: DEFAULT_HOTKEY,
  animation: { enabled: true, entrance: 'deck', exit: 'deck', speed: 1, stagger: 50 },
  macros: [],
  rolProfiles: [],
  pinnedActions: [],
  actions: { _default: [] },
};

const DEFAULT_PROFILE_ICONS = {
  Spotify: 'Music', chrome: 'Globe', ChatGPT: 'Sparkles', msedge: 'Globe', OUTLOOK: 'Mail',
  notepad: 'StickyNote', WhatsApp: 'MessageCircle', Telegram: 'Send', explorer: 'Folder', Code: 'Code',
};

// ---------------------------------------------------------------------------
// Configuración: vive en %APPDATA%\Actions Ring\config.json
// (antes se escribía junto al .exe, lo que rompía en USB o Program Files)
// ---------------------------------------------------------------------------
const CONFIG_DIR = app.getPath('userData');
const CONFIG_FILE = path.join(CONFIG_DIR, 'config.json');

function bundledConfigPath() {
  const candidates = [
    process.resourcesPath ? path.join(process.resourcesPath, 'config', 'default.json') : null,
    path.join(__dirname, '../../config/default.json'),
  ];
  return candidates.find((p) => p && fs.existsSync(p)) || null;
}

// Ubicaciones de versiones anteriores, para migrar la config del usuario una sola vez.
function legacyConfigPaths() {
  const list = [];
  if (process.env.PORTABLE_EXECUTABLE_DIR) {
    list.push(path.join(process.env.PORTABLE_EXECUTABLE_DIR, 'config', 'default.json'));
  }
  list.push(path.join(path.dirname(process.execPath), 'config', 'default.json'));
  list.push(path.join(__dirname, '../../config/default.json'));
  return list;
}

let nextId = 1;
function genId() {
  return `a${Date.now().toString(36)}${(nextId++).toString(36)}`;
}

function actionShapeKey(a) {
  return `${a.label}|${a.type}|${JSON.stringify(a.value)}`;
}

// Completa valores faltantes y asigna ids estables a cada acción.
// Devuelve { config, changed } para poder persistir la normalización.
function normalizeConfig(raw) {
  let changed = false;
  const cfg = raw && typeof raw === 'object' ? raw : {};

  if (typeof cfg.hotkey !== 'string' || !cfg.hotkey.trim()) { cfg.hotkey = DEFAULT_HOTKEY; changed = true; }
  if (!cfg.actions || typeof cfg.actions !== 'object' || Array.isArray(cfg.actions)) { cfg.actions = { _default: [] }; changed = true; }
  if (!Array.isArray(cfg.actions._default)) { cfg.actions._default = []; changed = true; }
  if (!Array.isArray(cfg.macros)) { cfg.macros = []; changed = true; }
  if (!Array.isArray(cfg.rolProfiles)) { cfg.rolProfiles = []; changed = true; }
  if (!Array.isArray(cfg.pinnedActions)) { cfg.pinnedActions = []; changed = true; }

  const anim = { ...DEFAULT_CONFIG.animation, ...(cfg.animation || {}) };
  if (JSON.stringify(anim) !== JSON.stringify(cfg.animation)) { cfg.animation = anim; changed = true; }

  // ids estables por acción
  const byShape = new Map();
  for (const key of Object.keys(cfg.actions)) {
    if (!Array.isArray(cfg.actions[key])) { cfg.actions[key] = []; changed = true; continue; }
    for (const action of cfg.actions[key]) {
      if (!action || typeof action !== 'object') continue;
      if (typeof action.id !== 'string' || !action.id) { action.id = genId(); changed = true; }
      if (!byShape.has(actionShapeKey(action))) byShape.set(actionShapeKey(action), action.id);
    }
  }

  // pinnedActions: formato nuevo = array de ids. Se migran los objetos viejos
  // resolviéndolos contra las acciones existentes; si no matchean, se conservan inline.
  const pinned = [];
  for (const entry of cfg.pinnedActions) {
    if (typeof entry === 'string') { pinned.push(entry); continue; }
    if (!entry || typeof entry !== 'object') { changed = true; continue; }
    const id = byShape.get(actionShapeKey(entry));
    if (id) { pinned.push(id); changed = true; }
    else {
      if (typeof entry.id !== 'string' || !entry.id) entry.id = genId();
      pinned.push(entry);
      changed = true;
    }
  }
  if (JSON.stringify(pinned) !== JSON.stringify(cfg.pinnedActions)) { cfg.pinnedActions = pinned; changed = true; }

  return { config: cfg, changed };
}

function loadConfig() {
  try { fs.mkdirSync(CONFIG_DIR, { recursive: true }); } catch { /* ignorado */ }

  // Migración de versiones anteriores
  if (!fs.existsSync(CONFIG_FILE)) {
    const legacy = legacyConfigPaths().find((p) => { try { return fs.existsSync(p); } catch { return false; } });
    if (legacy) {
      try { fs.copyFileSync(legacy, CONFIG_FILE); console.log(`[config] migrado desde ${legacy}`); }
      catch (e) { console.error('[config] no se pudo migrar:', e.message); }
    }
  }

  const sources = [CONFIG_FILE, bundledConfigPath()].filter(Boolean);
  for (const src of sources) {
    let raw;
    try { raw = fs.readFileSync(src, 'utf-8'); } catch { continue; }
    try {
      const { config: parsed, changed } = normalizeConfig(JSON.parse(raw));
      config = parsed;
      if (changed || src !== CONFIG_FILE) saveConfig(config);
      return config;
    } catch (e) {
      console.error(`[config] JSON inválido en ${src}: ${e.message}`);
      if (src === CONFIG_FILE) {
        const backup = `${CONFIG_FILE}.bad-${Date.now()}`;
        try { fs.renameSync(CONFIG_FILE, backup); console.error(`[config] respaldado como ${backup}`); } catch { /* ignorado */ }
      }
    }
  }

  // Último recurso: defaults en código, para que la app arranque siempre.
  console.error('[config] usando defaults embebidos');
  config = normalizeConfig(JSON.parse(JSON.stringify(DEFAULT_CONFIG))).config;
  saveConfig(config);
  return config;
}

// Escritura atómica: se escribe un .tmp y se renombra, así un corte
// a mitad de camino no deja el config corrupto.
function saveConfig(newConfig) {
  const { config: normalized } = normalizeConfig(newConfig);
  config = normalized;
  const tmp = `${CONFIG_FILE}.tmp`;
  try {
    fs.mkdirSync(CONFIG_DIR, { recursive: true });
    fs.writeFileSync(tmp, JSON.stringify(config, null, 2), 'utf-8');
    fs.renameSync(tmp, CONFIG_FILE);
  } catch (e) {
    console.error('[config] error al guardar:', e.message);
    try { fs.unlinkSync(tmp); } catch { /* ignorado */ }
  }
  return config;
}

// ---------------------------------------------------------------------------
// Foco de ventanas
// ---------------------------------------------------------------------------
function focusHwnd(hwnd) {
  if (!hwnd) return false;
  try {
    const pidBuf = [0];
    GetWindowThreadProcessId(hwnd, pidBuf);
    const targetThread = pidBuf[0];
    const ourThread = GetCurrentThreadId();
    if (targetThread && targetThread !== ourThread) {
      AttachThreadInput(ourThread, targetThread, true);
      SetForegroundWindow(hwnd);
      SetFocus(hwnd);
      AttachThreadInput(ourThread, targetThread, false);
    } else {
      SetForegroundWindow(hwnd);
    }
    return true;
  } catch {
    try { SetForegroundWindow(hwnd); return true; } catch { return false; }
  }
}

function restoreFocus() {
  if (lastActiveHwnd) focusHwnd(lastActiveHwnd);
}

// Recorre las ventanas visibles con título y llama a fn(hwnd, processName).
// Devolver true desde fn corta la enumeración.
function forEachWindow(fn) {
  let stop = false;
  const cb = koffi.register((hwnd) => {
    if (stop) return 1;
    try {
      if (!IsWindowVisible(hwnd)) return 1;
      if (GetWindowTextLengthW(hwnd) === 0) return 1;
      const pidBuf = [0];
      GetWindowThreadProcessId(hwnd, pidBuf);
      const pid = pidBuf[0];
      if (!pid) return 1;
      const hProcess = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, false, pid);
      if (!hProcess) return 1;
      const nameBuf = Buffer.alloc(520);
      const len = GetModuleBaseNameW(hProcess, null, nameBuf, 260);
      CloseHandle(hProcess);
      if (len > 0) {
        const name = nameBuf.toString('utf16le', 0, len * 2).replace(/\.exe$/i, '');
        if (fn(hwnd, name) === true) stop = true;
      }
    } catch { /* ventana inaccesible, seguir */ }
    return 1;
  }, koffi.pointer(WNDENUMPROC));
  try { EnumWindows(cb, 0); } finally { koffi.unregister(cb); }
}

function focusAppWindow(appName) {
  let target = null;
  const wanted = String(appName || '').toLowerCase();
  forEachWindow((hwnd, name) => {
    if (name.toLowerCase() === wanted) { target = hwnd; return true; }
    return false;
  });
  if (!target) return false;
  return focusHwnd(target);
}

function getActiveApp() {
  try {
    const hwnd = GetForegroundWindow();
    if (!hwnd) return '_default';
    lastActiveHwnd = hwnd;

    const pidBuf = [0];
    GetWindowThreadProcessId(hwnd, pidBuf);
    const pid = pidBuf[0];
    if (!pid) return '_default';

    const hProcess = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, false, pid);
    if (!hProcess) return '_default';

    const nameBuf = Buffer.alloc(520); // 260 chars * 2 bytes (UTF-16)
    const len = GetModuleBaseNameW(hProcess, null, nameBuf, 260);
    CloseHandle(hProcess);

    if (len === 0) return '_default';
    return nameBuf.toString('utf16le', 0, len * 2).replace(/\.exe$/i, '');
  } catch {
    return '_default';
  }
}

function getRunningApps() {
  const apps = new Set();
  forEachWindow((_hwnd, name) => { apps.add(name); return false; });
  return [...apps].sort((a, b) => a.localeCompare(b));
}

// ---------------------------------------------------------------------------
// Envío de teclas (SendInput nativo)
// ---------------------------------------------------------------------------
const VK_MAP = {
  a: 0x41, b: 0x42, c: 0x43, d: 0x44, e: 0x45, f: 0x46, g: 0x47,
  h: 0x48, i: 0x49, j: 0x4A, k: 0x4B, l: 0x4C, m: 0x4D, n: 0x4E,
  o: 0x4F, p: 0x50, q: 0x51, r: 0x52, s: 0x53, t: 0x54, u: 0x55,
  v: 0x56, w: 0x57, x: 0x58, y: 0x59, z: 0x5A,
  0: 0x30, 1: 0x31, 2: 0x32, 3: 0x33, 4: 0x34,
  5: 0x35, 6: 0x36, 7: 0x37, 8: 0x38, 9: 0x39,
  f1: 0x70, f2: 0x71, f3: 0x72, f4: 0x73, f5: 0x74, f6: 0x75,
  f7: 0x76, f8: 0x77, f9: 0x78, f10: 0x79, f11: 0x7A, f12: 0x7B,
  enter: 0x0D, return: 0x0D, tab: 0x09, escape: 0x1B, esc: 0x1B,
  space: 0x20, backspace: 0x08, delete: 0x2E, del: 0x2E,
  arrowup: 0x26, arrowdown: 0x28, arrowleft: 0x25, arrowright: 0x27,
  up: 0x26, down: 0x28, left: 0x25, right: 0x27,
  home: 0x24, end: 0x23, pageup: 0x21, pagedown: 0x22,
  insert: 0x2D, printscreen: 0x2C, capslock: 0x14, numlock: 0x90, pause: 0x13,
  '`': 0xC0, '-': 0xBD, '=': 0xBB, '[': 0xDB, ']': 0xDD, '\\': 0xDC,
  ';': 0xBA, "'": 0xDE, ',': 0xBC, '.': 0xBE, '/': 0xBF,
  plus: 0xBB, minus: 0xBD,
  control: 0xA2, ctrl: 0xA2, shift: 0xA0, alt: 0xA4, win: 0x5B, meta: 0x5B, super: 0x5B, cmd: 0x5B,
  rcontrol: 0xA3, rctrl: 0xA3, rshift: 0xA1, ralt: 0xA5,
  // AltGr en Windows es Alt derecho (VK_RMENU)
  altgr: 0xA5, altgraph: 0xA5,
};

// Teclas que requieren KEYEVENTF_EXTENDEDKEY
const EXTENDED_KEYS = new Set([0x25, 0x26, 0x27, 0x28, 0x24, 0x23, 0x21, 0x22, 0x2D, 0x2E, 0x5B, 0xA3, 0xA5, 0x90, 0x2C]);

// Devuelve los nombres de tecla que no se pueden reproducir. La UI lo usa
// para avisar antes de guardar una macro con pasos muertos.
function unmappedKeys(combo) {
  return String(combo || '')
    .split('+')
    .map((k) => k.trim())
    .filter((k) => k.length > 0 && VK_MAP[k.toLowerCase()] === undefined);
}

function writeInput(buf, index, { vk = 0, scan = 0, flags = 0 }) {
  const offset = index * INPUT_SIZE;
  let f = flags;
  if (vk && EXTENDED_KEYS.has(vk)) f |= KEYEVENTF_EXTENDEDKEY;
  buf.writeUInt32LE(INPUT_KEYBOARD, offset + OFF_TYPE);
  buf.writeUInt16LE(vk, offset + OFF_VK);
  buf.writeUInt16LE(scan, offset + OFF_SCAN);
  buf.writeUInt32LE(f, offset + OFF_FLAGS);
  buf.writeUInt32LE(0, offset + OFF_TIME);
  buf.writeBigUInt64LE(0n, offset + OFF_EXTRA);
}

function dispatchInputs(events) {
  if (!events.length) return;
  const buf = Buffer.alloc(INPUT_SIZE * events.length);
  events.forEach((ev, i) => writeInput(buf, i, ev));
  try {
    const sent = SendInput(events.length, buf, INPUT_SIZE);
    if (sent !== events.length) console.error(`[sendKeys] SendInput envió ${sent}/${events.length} eventos`);
  } catch (e) {
    console.error('[sendKeys] SendInput error:', e.message);
  }
}

function sendKeys(keys) {
  const combo = String(keys || '').trim();
  if (!combo) return;
  const parts = combo.split('+').map((k) => k.trim().toLowerCase()).filter(Boolean);
  if (!parts.length) return;
  const mainKey = parts.pop();
  const modifiers = parts;

  const missing = [mainKey, ...modifiers].filter((k) => VK_MAP[k] === undefined);
  if (missing.length) {
    console.error(`[sendKeys] tecla sin mapeo, paso ignorado: "${combo}" (${missing.join(', ')})`);
    return;
  }

  const events = [];
  for (const mod of modifiers) events.push({ vk: VK_MAP[mod], flags: 0 });
  events.push({ vk: VK_MAP[mainKey], flags: 0 });
  events.push({ vk: VK_MAP[mainKey], flags: KEYEVENTF_KEYUP });
  for (const mod of [...modifiers].reverse()) events.push({ vk: VK_MAP[mod], flags: KEYEVENTF_KEYUP });

  dispatchInputs(events);
}

// Escribe texto literal. Recorre unidades de código UTF-16 (no caracteres)
// para no romper emoji ni nada fuera del BMP, y manda Enter/Tab como
// teclas reales porque muchas apps ignoran \n enviado como Unicode.
function typeText(text) {
  const str = String(text ?? '');
  if (!str) return;
  const events = [];
  for (let i = 0; i < str.length; i++) {
    const code = str.charCodeAt(i);
    if (code === 13) continue; // \r de un \r\n: se emite con el \n
    if (code === 10) {
      events.push({ vk: VK_MAP.enter, flags: 0 }, { vk: VK_MAP.enter, flags: KEYEVENTF_KEYUP });
      continue;
    }
    if (code === 9) {
      events.push({ vk: VK_MAP.tab, flags: 0 }, { vk: VK_MAP.tab, flags: KEYEVENTF_KEYUP });
      continue;
    }
    events.push({ scan: code, flags: KEYEVENTF_UNICODE }, { scan: code, flags: KEYEVENTF_UNICODE | KEYEVENTF_KEYUP });
  }
  dispatchInputs(events);
}

// `delay` es la espera DESPUÉS de cada paso (semántica del editor y de los
// macros escritos a mano). Un 0 explícito se respeta: antes `|| 50` lo pisaba.
function executeMacro(steps) {
  const list = Array.isArray(steps) ? steps : [];
  let elapsed = 0;
  for (const step of list) {
    if (!step || typeof step !== 'object') continue;
    const keys = String(step.keys || '');
    setTimeout(() => {
      if (keys.startsWith('type:')) typeText(expandVariables(keys.slice(5), 'raw'));
      else sendKeys(keys);
    }, elapsed);
    const d = Number(step.delay);
    elapsed += Number.isFinite(d) && d >= 0 ? d : 50;
  }
}

// ---------------------------------------------------------------------------
// Variables dinámicas
// ---------------------------------------------------------------------------
// Caracteres con significado para cmd.exe. Al interpolar contenido del
// portapapeles (entrada no confiable) en un comando, se neutralizan.
const CMD_META = /["&|<>^%()!\r\n]/g;

/**
 * @param {string} value plantilla con {clipboard}, {date}, ...
 * @param {'raw'|'shell'|'url'} mode cómo se sanea lo interpolado
 */
function expandVariables(value, mode = 'raw') {
  const now = new Date();
  const sub = (text) => {
    const s = String(text ?? '');
    if (mode === 'url') return encodeURIComponent(s);
    if (mode === 'shell') return s.replace(CMD_META, ' ');
    return s;
  };
  return String(value ?? '')
    .replace(/\{clipboard\}/g, () => sub(clipboard.readText()))
    .replace(/\{date\}/g, () => sub(now.toLocaleDateString()))
    .replace(/\{time\}/g, () => sub(now.toLocaleTimeString()))
    .replace(/\{datetime\}/g, () => sub(now.toISOString()))
    .replace(/\{app\}/g, () => sub(lastActiveApp || ''));
}

// ---------------------------------------------------------------------------
// Historial de portapapeles
// ---------------------------------------------------------------------------
let lastClipText = '';
let suppressClipboardCapture = false;

function watchClipboard() {
  if (clipboardTimer) clearInterval(clipboardTimer);
  clipboardTimer = setInterval(() => {
    let text = '';
    try { text = clipboard.readText(); } catch { return; }
    if (!text || text === lastClipText) return;
    lastClipText = text;
    if (suppressClipboardCapture) return; // escritura propia (snippet)
    clipboardHistory.unshift(text);
    if (clipboardHistory.length > MAX_CLIPBOARD_HISTORY) clipboardHistory.pop();
  }, 1000);
}

// ---------------------------------------------------------------------------
// Ventanas
// ---------------------------------------------------------------------------
function createOverlay() {
  overlay = new BrowserWindow({
    width: 700,
    height: 700,
    show: false,
    frame: false,
    alwaysOnTop: true,
    skipTaskbar: true,
    resizable: false,
    hasShadow: false,
    backgroundColor: '#00000000',
    transparent: true,
    webPreferences: {
      preload: path.join(__dirname, 'preload-ring.js'),
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: false,
    },
  });
  overlay.setAlwaysOnTop(true, 'screen-saver');
  overlay.setVisibleOnAllWorkspaces(true);
  overlay.loadFile(path.join(__dirname, '../renderer/index.html'));

  // Red de seguridad: si el handler de React no corre (p. ej. el foco quedó
  // en otra parte del documento), Escape igual cierra el anillo.
  overlay.webContents.on('before-input-event', (_event, input) => {
    if (input.type === 'keyDown' && input.key === 'Escape') hideOverlay();
  });

  // Si el usuario pasa a otra ventana, el anillo no debe quedar colgado arriba.
  overlay.on('blur', () => {
    if (Date.now() - overlayShownAt < 400) return; // ignorar el blur de la propia apertura
    hideOverlay();
  });
}

function openSettings() {
  if (settingsWin && !settingsWin.isDestroyed()) { settingsWin.show(); settingsWin.focus(); return; }
  settingsWin = new BrowserWindow({
    width: 800,
    height: 620,
    minWidth: 640,
    minHeight: 480,
    title: 'Actions Ring',
    icon: path.join(__dirname, '../../icon.png'),
    backgroundColor: '#0f1923',
    webPreferences: {
      preload: path.join(__dirname, 'preload-settings.js'),
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: false,
    },
  });
  settingsWin.setMenuBarVisibility(false);
  settingsWin.loadFile(path.join(__dirname, '../settings/index.html'));
  settingsWin.on('closed', () => {
    settingsWin = null;
    // Si se cerró en medio de una grabación, los hotkeys quedaban muertos.
    if (recordingActive) { recordingActive = false; registerHotkey(config.hotkey); }
  });
}

function profileIconFor(name) {
  const custom = (config && config.profileIcons) || {};
  return custom[name] || DEFAULT_PROFILE_ICONS[name] || 'AppWindow';
}

// Busca el perfil del proceso activo. El match es case-insensitive: antes
// "Chrome" vs "chrome" caía al default en silencio.
function profileActionsFor(appName) {
  const all = (config && config.actions) || {};
  if (Array.isArray(all[appName])) return all[appName];
  const wanted = String(appName || '').toLowerCase();
  const key = Object.keys(all).find((k) => k.toLowerCase() === wanted);
  if (key && Array.isArray(all[key])) return all[key];
  return Array.isArray(all._default) ? all._default : [];
}

function actionsById() {
  const index = new Map();
  for (const list of Object.values((config && config.actions) || {})) {
    if (!Array.isArray(list)) continue;
    for (const action of list) if (action && action.id) index.set(action.id, action);
  }
  return index;
}

// Las pinned se guardan por id, así renombrar o editar la acción original
// se refleja solo. Se aceptan objetos inline de configs viejas.
function resolvePinnedActions() {
  const index = actionsById();
  const out = [];
  for (const entry of (config.pinnedActions || [])) {
    const action = typeof entry === 'string' ? index.get(entry) : entry;
    if (action && typeof action === 'object') out.push({ ...action, _pinned: true });
  }
  return out;
}

function positionOverlayAtCursor() {
  const cursor = screen.getCursorScreenPoint();
  const display = screen.getDisplayNearestPoint(cursor);
  const area = display.workArea;
  const [w, h] = overlay.getSize();
  const clamp = (pos, min, size, total) => {
    if (total < size) return Math.round(min + (total - size) / 2); // pantalla más chica que el anillo
    return Math.round(Math.min(Math.max(pos, min), min + total - size));
  };
  overlay.setPosition(
    clamp(cursor.x - w / 2, area.x, w, area.width),
    clamp(cursor.y - h / 2, area.y, h, area.height),
  );
}

function hideOverlay() {
  if (!overlay || overlay.isDestroyed()) return;
  // Escape se registra solo mientras el anillo está abierto: registrarlo de
  // forma permanente lo secuestraba para todo el sistema operativo.
  try { globalShortcut.unregister('Escape'); } catch { /* ignorado */ }
  if (overlay.isVisible()) overlay.hide();
}

function showOverlay() {
  const activeApp = getActiveApp();
  lastActiveApp = activeApp;

  const pinned = resolvePinnedActions();
  const pinnedIds = new Set(pinned.map((a) => a.id).filter(Boolean));
  const pinnedLabels = new Set(pinned.map((a) => a.label));
  const actions = [
    ...pinned,
    ...profileActionsFor(activeApp).filter((a) => a && !pinnedIds.has(a.id) && !pinnedLabels.has(a.label)),
  ];

  const rolProfiles = (config.rolProfiles || []).map((name) => ({
    name,
    icon: profileIconFor(name),
    actions: profileActionsFor(name).slice(0, 6),
  }));

  overlay.webContents.send('show-ring', {
    actions,
    activeApp,
    rolProfiles,
    animation: config.animation || {},
    macros: config.macros || [],
  });

  positionOverlayAtCursor();
  overlayShownAt = Date.now();
  overlay.show();
  overlay.focus();
  try { globalShortcut.register('Escape', hideOverlay); } catch { /* ignorado */ }
}

function toggleOverlay() {
  if (!overlay || overlay.isDestroyed()) return;
  if (overlay.isVisible()) hideOverlay();
  else showOverlay();
}

// ---------------------------------------------------------------------------
// Hotkey
// ---------------------------------------------------------------------------
function unregisterHotkey() {
  if (!activeHotkey) return;
  try { globalShortcut.unregister(activeHotkey); } catch { /* ignorado */ }
  activeHotkey = null;
}

// Un accelerator inválido hacía explotar el handler de IPC y dejaba la app
// sin ningún hotkey hasta reiniciar. Ahora se captura y se cae al default.
function registerHotkey(accelerator) {
  unregisterHotkey();
  const attempt = (accel) => {
    if (typeof accel !== 'string' || !accel.trim()) return false;
    try {
      if (globalShortcut.register(accel, toggleOverlay)) { activeHotkey = accel; return true; }
      console.error(`[hotkey] "${accel}" rechazado (¿lo tiene otra app?)`);
    } catch (e) {
      console.error(`[hotkey] "${accel}" inválido: ${e.message}`);
    }
    return false;
  };

  if (attempt(accelerator)) return activeHotkey;
  if (accelerator !== DEFAULT_HOTKEY && attempt(DEFAULT_HOTKEY)) {
    console.error(`[hotkey] usando el default ${DEFAULT_HOTKEY}`);
    return activeHotkey;
  }
  console.error('[hotkey] no se pudo registrar ningún hotkey; usá el ícono del tray');
  return null;
}

function updateTrayTooltip() {
  if (tray && !tray.isDestroyed()) {
    tray.setToolTip(`Actions Ring (${activeHotkey || 'sin hotkey'})`);
  }
}

function createTray() {
  const icon = nativeImage
    .createFromPath(path.join(__dirname, '../../icon.png'))
    .resize({ width: 16, height: 16 });
  tray = new Tray(icon);
  tray.setContextMenu(Menu.buildFromTemplate([
    { label: 'Abrir anillo', click: toggleOverlay },
    { label: 'Settings', click: openSettings },
    { type: 'separator' },
    { label: 'Abrir carpeta de configuración', click: () => shell.openPath(CONFIG_DIR) },
    {
      label: 'Iniciar con Windows',
      type: 'checkbox',
      checked: app.getLoginItemSettings().openAtLogin,
      click: (item) => app.setLoginItemSettings({ openAtLogin: item.checked }),
    },
    { type: 'separator' },
    { label: 'Salir', click: () => app.quit() },
  ]));
  tray.on('click', toggleOverlay);
  updateTrayTooltip();
}

// ---------------------------------------------------------------------------
// Ejecución de acciones
// ---------------------------------------------------------------------------
function spawnDetached(cmdline) {
  try {
    const child = spawn('cmd.exe', ['/c', cmdline], { detached: true, stdio: 'ignore', windowsHide: true });
    child.on('error', (e) => console.error('[exec] error:', e.message));
    child.unref();
  } catch (e) {
    console.error('[exec] no se pudo lanzar:', e.message);
  }
}

// Abre una app, archivo, carpeta o URL sin pasar por el shell cuando se puede.
function openTarget(value) {
  const target = String(value || '').trim();
  if (!target) return;
  if (/^[a-z][a-z0-9+.-]*:\/\//i.test(target)) { shell.openExternal(target); return; }
  if (/[\\/:]/.test(target) && fs.existsSync(target)) { shell.openPath(target); return; }
  if (CMD_META.test(target)) {
    console.error(`[open] valor con caracteres no permitidos, ignorado: ${target}`);
    return;
  }
  // `start` resuelve nombres cortos vía App Paths del registro (notepad, chrome, ...)
  spawnDetached(`start "" "${target}"`);
}

const WINDOW_SNAP_KEYS = { left: 'Win+ArrowLeft', right: 'Win+ArrowRight', maximize: 'Win+ArrowUp' };

function executeAction(action) {
  if (!action || typeof action !== 'object') return;
  switch (action.type) {
    case 'shortcut':
      sendKeys(action.value);
      break;

    case 'open':
      openTarget(action.value);
      break;

    case 'command': {
      const template = String(action.value || '');

      if (template.startsWith('window:')) {
        const pos = template.slice('window:'.length).trim().toLowerCase();
        if (WINDOW_SNAP_KEYS[pos]) sendKeys(WINDOW_SNAP_KEYS[pos]);
        else console.error(`[command] window:${pos} no reconocido`);
        break;
      }

      // URLs directas o `start <url>`: se abren con el navegador por defecto,
      // sin shell, y lo interpolado se codifica para URL (antes un clipboard
      // con espacios rompía la query y uno con `&` inyectaba comandos).
      const urlOnly = template.match(/^(?:start\s+(?:""\s+)?)?((?:https?|mailto):\S*)$/i);
      if (urlOnly) { shell.openExternal(expandVariables(urlOnly[1], 'url')); break; }

      spawnDetached(expandVariables(template, 'shell'));
      break;
    }

    case 'snippet': {
      const text = expandVariables(action.value, 'raw');
      const previous = clipboard.readText();
      suppressClipboardCapture = true;
      clipboard.writeText(text);
      lastClipText = text;
      setTimeout(() => {
        sendKeys('Control+V');
        // Devolver el portapapeles como estaba: antes el snippet lo pisaba para siempre.
        setTimeout(() => {
          try { clipboard.writeText(previous); lastClipText = previous; } catch { /* ignorado */ }
          suppressClipboardCapture = false;
        }, 400);
      }, 120);
      break;
    }

    case 'workflow': {
      let steps;
      try {
        steps = typeof action.value === 'string' ? JSON.parse(action.value) : action.value;
      } catch (e) {
        console.error('[workflow] JSON inválido:', e.message);
        break;
      }
      if (!Array.isArray(steps)) { console.error('[workflow] se esperaba un array de acciones'); break; }
      steps.forEach((step, i) => setTimeout(() => executeAction(step), i * 300));
      break;
    }

    case 'macro': {
      let steps;
      try {
        steps = typeof action.value === 'string' ? JSON.parse(action.value) : action.value;
      } catch (e) {
        console.error('[macro] JSON inválido:', e.message);
        break;
      }
      executeMacro(steps);
      break;
    }

    default:
      console.error(`[action] tipo desconocido: ${action.type}`);
  }
}

// ---------------------------------------------------------------------------
// IPC
// ---------------------------------------------------------------------------
function registerIpc() {
  ipcMain.on('execute-action', (_event, action) => {
    if (!action || typeof action !== 'object') return;

    // Sub-anillo: navegar a otro perfil sin cerrar
    if (action.type === 'profile') {
      if (!overlay || overlay.isDestroyed()) return;
      overlay.webContents.send('show-ring', {
        actions: profileActionsFor(action.value),
        activeApp: action.value,
        rolProfiles: [],
        animation: config.animation || {},
        macros: [],
        isSubring: true,
      });
      return;
    }

    hideOverlay();

    if (action._fromProfile) {
      // Acción de un perfil Rol: primero traer esa app al frente
      if (!focusAppWindow(action._fromProfile)) openTarget(action._fromProfile);
      setTimeout(() => executeAction(action), 400);
    } else {
      restoreFocus();
      setTimeout(() => executeAction(action), 200);
    }
  });

  ipcMain.on('execute-macro', (_event, macro) => {
    hideOverlay();
    restoreFocus();
    const steps = macro && Array.isArray(macro.steps) ? macro.steps : [];
    setTimeout(() => executeMacro(steps), 200);
  });

  ipcMain.on('close-ring', () => hideOverlay());
  ipcMain.on('renderer-log', (_event, msg) => console.log('[renderer]', msg));

  ipcMain.handle('get-config', () => config);

  ipcMain.handle('save-config', (_event, newConfig) => {
    const previousHotkey = config && config.hotkey;
    saveConfig(newConfig);
    if (config.hotkey !== previousHotkey && !recordingActive) {
      registerHotkey(config.hotkey);
      updateTrayTooltip();
    }
    return { config, hotkey: activeHotkey };
  });

  ipcMain.handle('get-running-apps', () => getRunningApps());
  ipcMain.handle('get-clipboard-history', () => clipboardHistory);
  ipcMain.handle('clear-clipboard-history', () => { clipboardHistory = []; return clipboardHistory; });
  ipcMain.handle('get-config-path', () => CONFIG_FILE);
  ipcMain.handle('open-config-folder', () => shell.openPath(CONFIG_DIR));
  ipcMain.handle('validate-keys', (_event, combo) => unmappedKeys(combo));

  // Durante la grabación hay que liberar el hotkey para no interceptar teclas.
  // La captura real ocurre en la ventana de Settings.
  ipcMain.handle('start-recording', () => {
    recordingActive = true;
    unregisterHotkey();
    updateTrayTooltip();
    return true;
  });

  ipcMain.handle('stop-recording', () => {
    recordingActive = false;
    registerHotkey(config.hotkey);
    updateTrayTooltip();
    return true;
  });
}

// ---------------------------------------------------------------------------
// Arranque
// ---------------------------------------------------------------------------
function main() {
  app.on('second-instance', () => openSettings());

  // Es una app de bandeja: cerrar Settings no debe terminar el proceso.
  app.on('window-all-closed', () => { /* se sale desde el menú del tray */ });

  app.whenReady().then(() => {
    loadConfig();
    createOverlay();
    createTray();
    registerIpc();
    watchClipboard();
    registerHotkey(config.hotkey);
    updateTrayTooltip();
    console.log(`[config] ${CONFIG_FILE}`);
    console.log(`[hotkey] ${activeHotkey || 'ninguno'}`);
  });

  app.on('will-quit', () => {
    globalShortcut.unregisterAll();
    if (clipboardTimer) clearInterval(clipboardTimer);
  });
}

// Una sola instancia: dos procesos competían por el hotkey y por el config.
if (!app.requestSingleInstanceLock()) app.quit();
else main();

