    assert.ok(h.calls.registeredHotkeys.length > before, 'tiene que haber registrado algo');
    assert.ok(h.calls.errors.some((e) => e.includes('inválido')), 'tiene que loguear el error');
  });

  test('la app queda con un hotkey activo, no sin ninguno', () => {
    const last = h.calls.registeredHotkeys[h.calls.registeredHotkeys.length - 1];
    assert.equal(last, 'Control+Alt+Space');
  });

  test('guardar un hotkey válido lo registra', () => {
    const result = h.ipc.handle.get('save-config')(null, { ...SAMPLE, hotkey: 'Control+Shift+F12' });
    assert.equal(result.hotkey, 'Control+Shift+F12');
  });

  h.restore();
}

// --------------------------------------------------------------------------
console.log('\nmain.js — config corrupta y faltante');
{
  const dir = tmpDir('corrupt');
  seedConfig(dir, '{ esto no es json valido ');
  const h = makeHarness({ userDataDir: dir });

  test('arranca igual con un config corrupto', () => {
    assert.deepEqual(h.calls.registeredHotkeys.length > 0, true, 'tiene que haber registrado el hotkey');
  });

  test('respalda el archivo corrupto como .bad-<timestamp>', () => {
    const backups = fs.readdirSync(dir).filter((f) => f.includes('.bad-'));
    assert.equal(backups.length, 1, `se esperaba 1 respaldo, hay ${backups.length}`);
  });

  test('deja un config válido escrito', () => {
    const written = JSON.parse(fs.readFileSync(path.join(dir, 'config.json'), 'utf-8'));
    assert.ok(written.hotkey);
    assert.ok(written.actions._default);
  });

  h.restore();
}

{
  const dir = tmpDir('missing'); // no se escribe ningún config
  const h = makeHarness({ userDataDir: dir });

  test('sin config previa migra/crea una desde los defaults publicados', () => {
    const written = JSON.parse(fs.readFileSync(path.join(dir, 'config.json'), 'utf-8'));
    assert.ok(Array.isArray(written.actions._default));
    assert.ok(written.actions._default.length > 0, 'tiene que traer las acciones por defecto');
  });

  h.restore();
}

// --------------------------------------------------------------------------
console.log('\nmain.js — ejecución de acciones');
{
  const dir = tmpDir('exec');
  seedConfig(dir, JSON.stringify(SAMPLE));
  const h = makeHarness({ userDataDir: dir });

  test('una acción de tipo open con URL va al navegador, no al shell', () => {
    h.ipc.on.get('execute-action')(null, { type: 'open', value: 'https://canva.com' });
    // executeAction corre con un setTimeout de 200 ms; se verifica abajo.
    assert.ok(true);
  });

  test('clear-clipboard-history vacía el historial', () => {
    assert.deepEqual(h.ipc.handle.get('clear-clipboard-history')(), []);
  });

  test('start/stop-recording libera y vuelve a registrar el hotkey', () => {
    const unregBefore = h.calls.unregistered.length;
    h.ipc.handle.get('start-recording')();
    assert.ok(h.calls.unregistered.length > unregBefore, 'start-recording tiene que liberar el hotkey');
    const regBefore = h.calls.registeredHotkeys.length;
    h.ipc.handle.get('stop-recording')();
    assert.ok(h.calls.registeredHotkeys.length > regBefore, 'stop-recording tiene que volver a registrarlo');
  });

  setTimeout(() => {
    test('la URL se abrió con shell.openExternal', () => {
      assert.deepEqual(h.calls.openedExternal, ['https://canva.com']);
    });
    h.restore();

    console.log(`\n${passed} ok, ${failed} fallidos`);
    process.exit(failed ? 1 : 0);
  }, 400);
}

